package space.seclume.crypto;

import java.lang.foreign.MemorySegment;
import java.lang.foreign.ValueLayout;

import space.seclume.secret.SecretScope;

/**
 * New signing keys, made where they will live.
 *
 * <p>A P-256 key is generated by the backend ({@link NativeP256}), written as
 * an SEC 1 {@code ECPrivateKey} into locked native memory - the scalar copied
 * from the backend into the structure and nowhere else - and decoded by the
 * same backend as a signing key. The structure is wiped when the key is made;
 * the key then exists in OpenSSL or CNG only. The scalar never passes through
 * a Java array.
 */
final class SigningKeys {

    /** {@code SEQUENCE { INTEGER 1, OCTET STRING (32) d, [0] prime256v1, [1] BIT STRING point }}. */
    static final int SEC1_P256_LENGTH = 121;
    private static final byte[] HEAD = {0x30, 0x77, 0x02, 0x01, 0x01, 0x04, 0x20};
    private static final byte[] MIDDLE = {
        (byte) 0xa0, 0x0a, 0x06, 0x08, 0x2a, (byte) 0x86, 0x48, (byte) 0xce, 0x3d, 0x03, 0x01,
        0x07, (byte) 0xa1, 0x44, 0x03, 0x42, 0x00};
    private static final int SCALAR_AT = HEAD.length;
    private static final int POINT_AT = SCALAR_AT + NativeP256.SECRET_SIZE + MIDDLE.length;

    private SigningKeys() {
    }

    static PrivateSigningKey p256() {
        try (NativeP256 generated = NativeP256.generate();
             SecretScope der = SecretScope.allocate(SEC1_P256_LENGTH)) {
            MemorySegment out = der.segment();
            MemorySegment.copy(HEAD, 0, out, ValueLayout.JAVA_BYTE, 0, HEAD.length);
            generated.privateScalar(out.asSlice(SCALAR_AT, NativeP256.SECRET_SIZE));
            MemorySegment.copy(MIDDLE, 0, out, ValueLayout.JAVA_BYTE,
                    SCALAR_AT + NativeP256.SECRET_SIZE, MIDDLE.length);
            generated.publicKey(out.asSlice(POINT_AT, NativeP256.PUBLIC_SIZE));
            der.length(SEC1_P256_LENGTH);
            return PrivateSigningKey.decode(out, SEC1_P256_LENGTH);
        }
    }
}
